function showMyPage(){setDrawer(false);['home-page','product-page','checkout-page'].forEach(id=>document.getElementById(id).hidden=true);document.getElementById('mypage-page').hidden=false;renderMyPage();window.scrollTo({top:0,behavior:'instant'})}
function orderDate(order){const value=order.createdAt;return value?.toDate?value.toDate():value?.seconds?new Date(value.seconds*1000):new Date()}
function renderMyPage(){
 const panel=document.getElementById('mypage-content');if(!panel)return;
 const user=window.moodnoteUser,orders=user?(window.moodnoteOrders||[]):[],saved=(user?favorites:[]).map(byId).filter(Boolean),count=Object.values(cart).reduce((a,b)=>a+b,0);
 panel.innerHTML=`<a href="#catalog" data-home class="back-link">← 문구 구경하기</a><div class="account-title"><span class="eyebrow">MY MOODNOTE</span><h1>마이페이지</h1><p>주문과 혜택, 저장한 취향을 한곳에서 확인하세요.</p></div><section class="account-profile"><img class="account-mark" src="assets/moodnote-mark-v2.svg" alt=""/><div><h2>${user?esc(window.moodnoteProfile?.displayName||user.displayName||'무드노트 회원')+'님, 반가워요.':'오늘의 취향을 모아볼까요?'}</h2><p>${user?esc(user.email||'Google 계정으로 로그인 중입니다.'):'Google 계정으로 로그인하고 나의 주문과 찜, 배송지를 확인하세요.'}</p></div><button class="outline-button" data-account-action="${user?'logout':'login'}">${user?'로그아웃':'Google 로그인'}</button></section><div class="account-stats"><button data-account-scroll="my-orders"><strong>${orders.length}</strong><span>주문내역</span></button><button data-account-scroll="my-favorites"><strong>${saved.length}</strong><span>찜한 상품</span></button><button data-action="cart"><strong>${count}</strong><span>장바구니</span></button></div><p class="account-note">회원의 장바구니와 찜은 계정에 저장됩니다. 로그아웃하면 화면에서 비워지고, 다시 로그인하면 불러올 수 있어요.</p><div id="account-panels"><section class="account-section active" id="my-orders"><div class="account-section-head"><h2>주문 내역</h2><span>${orders.length}건</span></div>${orders.length?orders.map(order=>`<article class="account-order"><header><div><time>${esc(orderDate(order).toLocaleDateString('ko-KR'))}</time><b>${esc(order.id)}</b></div><span class="account-demo">${esc(order.status||'결제 확인 중')}</span></header>${(order.items||[]).map(item=>`<div class="account-order-item"><button data-product="${esc(item.id)}" aria-label="${esc(item.name)} 상세 보기"><img src="${esc(item.image)}" alt="${esc(item.name)}"/></button><div><button class="account-product-name" data-product="${esc(item.id)}">${esc(item.name)}</button><p>${esc(item.option)} · ${item.quantity}개</p></div><strong>${won(item.price*item.quantity)}</strong></div>`).join('')}<details class="order-details"><summary>주문 상세정보</summary><p>상품 수량 ${(order.items||[]).reduce((n,item)=>n+item.quantity,0)}개 · 주문번호 ${esc(order.id)}</p><p>현재 처리 상태: ${esc(order.status||'확인 중')}</p>${order.carrier&&order.trackingNumber?`<p>배송: ${esc(order.carrier)} · 송장번호 ${esc(order.trackingNumber)}</p>`:''}${order.claimStatus?`<p>교환·반품 처리: ${esc(order.claimStatus)}</p>`:''}${order.refundedAmount?`<p>환불 금액: ${won(order.refundedAmount)}</p>`:''}${order.receiptUrl?`<a href="${esc(order.receiptUrl)}" target="_blank" rel="noopener">결제 영수증 보기 ↗</a>`:''}</details><footer><span>배송비 포함 결제 금액</span><strong>${won(order.total)}</strong></footer></article>`).join(''):`<div class="account-empty"><span aria-hidden="true">▤</span><h3>아직 주문한 문구가 없어요</h3><p>토스 결제를 완료한 주문이 여기에 표시됩니다.</p><a href="#catalog" data-home class="outline-button">상품 둘러보기</a></div>`}</section><section class="account-section" id="my-favorites" hidden><div class="account-section-head"><h2>찜한 상품</h2><span>${saved.length}개</span></div>${saved.length?`<div class="account-favorites">${saved.map(p=>productCard(p)).join('')}</div>`:`<div class="account-empty"><span aria-hidden="true">♡</span><h3>마음에 드는 문구에 하트를 눌러보세요</h3><p>다음에 다시 보고 싶은 상품을 모아둘 수 있어요.</p><a href="#catalog" data-home class="outline-button">취향 찾으러 가기</a></div>`}</section></div><section class="account-help"><div><h2>도움이 필요하세요?</h2><p>배송·교환 안내와 고객센터 운영 시간을 확인하세요.</p></div><a href="support.html" class="text-link">고객센터 →</a></section>`;
 renderAddressBook();renderAccountExtras();activateAccountPanel(window.accountPanel||'my-orders');
}
function activateAccountPanel(id){window.accountPanel=id;document.querySelectorAll('#account-panels > .account-section').forEach(section=>{section.hidden=section.id!==id;section.classList.toggle('active',section.id===id)});document.querySelectorAll('.account-nav [data-account-scroll]').forEach(link=>{const active=link.dataset.accountScroll===id;link.classList.toggle('active',active);link.setAttribute('aria-current',active?'page':'false')});document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
document.addEventListener('click',event=>{const link=event.target.closest('[data-mypage]');if(link){event.preventDefault();history.pushState({},'','#mypage');showMyPage();return}const menu=event.target.closest('.account-nav [data-account-scroll],.account-stats [data-account-scroll]');if(menu){event.preventDefault();activateAccountPanel(menu.dataset.accountScroll);return}const action=event.target.closest('[data-account-action]');if(action){if(action.dataset.accountAction==='login')document.getElementById('auth-button').click();else document.getElementById('auth-logout').click()}});
window.addEventListener('moodnote-auth-change',()=>{if(!document.getElementById('mypage-page').hidden)renderMyPage()});
window.addEventListener('moodnote-orders',()=>{if(!document.getElementById('mypage-page').hidden)renderMyPage()});
window.addEventListener('moodnote-profile',()=>{if(!document.getElementById('mypage-page').hidden)renderMyPage()});
window.addEventListener('hashchange',()=>{if(location.hash==='#mypage')showMyPage()});if(location.hash==='#mypage')showMyPage();
